package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class XVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property x of observed panel ")
  void test_xvo_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> XVO.tryFrom(null));
    Assertions.assertEquals(1, XVO.from(1).getX());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> XVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", XVO.from(1).toString());
  }
}
